const oracle = await import(
  'data:text/javascript;base64,' + Buffer.from(sourceOracleCode).toString('base64')
);
const lines = Array.from({ length: 96 }, (_, i) => ({
  fullText: '镜台 Hello ' + i,
  startTime: i * 5,
  endTime: i * 5 + 4,
  words: [
    { text: '镜台', startTime: i * 5, endTime: i * 5 + 2 },
    { text: 'Hello', startTime: i * 5 + 2, endTime: i * 5 + 4 },
  ],
  blockIndex: Math.floor(i / 4),
  isChorus: i % 12 >= 8,
  songPart: i % 12 >= 8 ? 'chorus' : 'verse',
}));
const plain = (value) => JSON.parse(JSON.stringify(value));
test('every shipped Diorama runtime stays inside the real ES2016 package parser', async () => {
  const folder = new URL('../plugins/folia-lyrics-skin/qml/styles/diorama/', import.meta.url);
  for (const name of await readdir(folder))
    if (name.endsWith('.mjs'))
      parse(await readFile(new URL(name, folder), 'utf8'), {
        ecmaVersion: 2016,
        sourceType: 'module',
      });
});
test('flat independent geometry fields assemble the original nested tuning atomically', () => {
  const result = K.tuning({
    dioramaGeometryEnabled: false,
    dioramaGeometryMode: 'corridor',
    dioramaGeometryStrands: false,
    dioramaGeometryRings: false,
  });
  assert.deepEqual(result.geometryVisibility, {
    enabled: false,
    mode: 'corridor',
    strands: false,
    blobs: true,
    ribbons: true,
    rings: false,
  });
  assert.equal(result.particleDensity, K.DEFAULT_DIORAMA_TUNING.particleDensity);
});
test('packed Worker transport preserves every possible UTF16 word including NUL and surrogate units', () => {
  const bytes = new ArrayBuffer(65536 * 4),
    view = new DataView(bytes);
  for (let i = 0; i < 65536; i++) {
    view.setUint16(i * 4, i, true);
    view.setUint16(i * 4 + 2, 0x3f80, true);
  }
  const packed = packFloatWords(bytes);
  assert.equal(packed.length, 65536 * 2);
  for (let i = 0; i < 65536; i++) {
    assert.equal(packed.charCodeAt(i * 2), i);
    assert.equal(packed.charCodeAt(i * 2 + 1), 0x3f80);
  }
});
test('pinned camera/path/placement/all thirteen shots match independent source oracle', () => {
  const shots = new Set();
  for (const seed of ['diorama', 'echo-music', 123])
    for (const mode of ['calm', 'normal', 'chaotic']) {
      assert.deepEqual(
        K.buildDioramaPath(lines.length, seed),
        oracle.buildDioramaPath(lines.length, seed),
      );
      for (let i = 0; i < lines.length; i++) {
        const shot = K.getDioramaShot(i, lines, seed, mode);
        shots.add(shot);
        assert.equal(shot, oracle.getDioramaShot(i, lines, seed, mode));
        const placement = K.getDioramaTextPlacement(i, seed, 1.35);
        assert.deepEqual(placement, oracle.getDioramaTextPlacement(i, seed, 1.35));
        for (const progress of [0, 0.15, 0.5, 0.9, 1]) {
          const ctx = {
            progress,
            wordProgress: progress,
            hero: 5.2,
            lift: 0.5,
            seed,
            lineIndex: i,
            moveScale: 1.6,
          };
          assert.deepEqual(K.resolveShotOffset(shot, ctx), oracle.resolveShotOffset(shot, ctx));
        }
        const frame = K.buildDioramaPath(lines.length, seed)[i];
        assert.deepEqual(
          K.buildFormation(i, seed, shot, frame, placement, 1.6),
          oracle.buildFormation(i, seed, shot, frame, placement, 1.6),
        );
      }
    }
  assert.equal(shots.size, 13);
});
test('all welded point-cloud surfaces and corridor buffers match original float32 values', () => {
  for (const kind of ['box', 'sphere', 'cone', 'torus'])
    for (const density of [96, 576, 1536])
      for (const stretch of [1, 1.5, 3.4])
        assert.deepEqual(
          K.buildDioramaStructuredSurface(kind, density, stretch),
          oracle.buildDioramaStructuredSurface(kind, density, stretch),
        );
  const seq = K.createSequencerState(),
    other = oracle.createSequencerState();
  for (const api of [K, oracle])
    api.appendSegment(api === K ? seq : other, {
      seed: 'buffer',
      lines,
      round: 0,
      placementOrigin: { x: 2, y: -3, z: -40 },
    });
  const spans = K.buildDioramaParticleCorridorWindow(seq, 8, 6, 7),
    expected = oracle.buildDioramaParticleCorridorWindow(other, 8, 6, 7);
  assert.deepEqual(spans, expected);
  for (const density of [96, 576, 1536])
    assert.deepEqual(
      K.buildDioramaCorridorGeometryData(spans, density),
      oracle.buildDioramaCorridorGeometryData(expected, density),
    );
});
test('sequencer late lyrics, translation, pruning and 46-unit song flight stay identical', () => {
  const a = K.createSequencerState(),
    b = oracle.createSequencerState();
  for (let i = 0; i < 6; i++) {
    const input = {
      seed: 'song-' + i,
      lines: i === 0 ? [] : lines.slice(0, 8),
      round: 0,
      placementOrigin: K.pickTransitionOffset('song-' + i, i + 1),
    };
    K.appendSegment(a, input);
    oracle.appendSegment(b, input);
    assert.deepEqual(a, b);
    if (i === 0) {
      K.updateActiveSegmentLines(a, lines.slice(0, 5));
      oracle.updateActiveSegmentLines(b, lines.slice(0, 5));
      assert.deepEqual(a, b);
    }
    K.pruneSegments(a, a.nextGlobalStart - 12);
    oracle.pruneSegments(b, b.nextGlobalStart - 12);
    assert.deepEqual(a, b);
  }
  for (let t = -1; t <= 2; t += 0.05) assert.equal(K.transitionEase(t), oracle.transitionEase(t));
});
test('audio valley/peak hysteresis, elastic spring and source lifecycle match oracle', () => {
  const a = K.createDioramaBandTracker(),
    b = oracle.createDioramaBandTracker(),
    ea = K.createDioramaParticleElasticState(),
    eb = oracle.createDioramaParticleElasticState();
  let onsets = 0;
  for (let i = 0; i < 2400; i++) {
    const level = i % 30 < 6 ? 0.8 : 0.04;
    const actual = K.stepDioramaBandTracker(a, level, 1 / 60),
      expected = oracle.stepDioramaBandTracker(b, level, 1 / 60);
    assert.deepEqual(actual, expected);
    if (actual.onset) onsets++;
    const target = K.resolveDioramaPulseTarget(1 + actual.transient * 0.14, 1.5, i % 2 === 0);
    assert.equal(
      K.stepDioramaParticleElasticResponse(ea, target, 1 / 60),
      oracle.stepDioramaParticleElasticResponse(eb, target, 1 / 60),
    );
  }
  assert.ok(onsets > 70);
  for (let d = 0; d < 60; d += 0.2) {
    assert.equal(K.resolveTextLife(d), oracle.resolveTextLife(d));
    assert.equal(K.resolveShapeLifeOpacity(d), oracle.resolveShapeLifeOpacity(d));
  }
  for (let now = -1; now < 10; now += 0.01)
    assert.equal(
      K.resolveGradientEnergy(now, { startTime: 1, endTime: 3 }),
      oracle.resolveGradientEnergy(now, { startTime: 1, endTime: 3 }),
    );
});
